mapper.sql:
FROM publications p JOIN categories cat ON cat.id=p.category_id
JOIN publication_reading_progress own ON own.publication_id=p.id AND own.user_id=#{userId}
JOIN publication_reactions own ON own.publication_id=p.id AND own.user_id=#{userId} AND own.kind=#{kind}
WHERE p.is_deleted=false AND cat.is_deleted=false AND p.status='PUBLISHED' AND p.delivery_status='AVAILABLE'
AND p.access_type='FREE'

mapper.select:
SELECT 

ORDER BY own.updated_at DESC, own.id DESCORDER BY own.created_at DESC, own.id DESC
LIMIT #{size} OFFSET #{offset}
